import{_ as e,o as t,c as l,ag as o}from"./chunks/framework.CAXxHpAX.js";const s=JSON.parse('{"title":"法执","description":"","frontmatter":{},"headers":[],"relativePath":"50-概念资料/dict-法执.md","filePath":"50-概念资料/dict-法执.md","lastUpdated":1778033203000}'),i={name:"50-概念资料/dict-法执.md"};function r(u,a,c,d,h,n){return t(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="法执" tabindex="-1">法执 <a class="header-anchor" href="#法执" aria-label="Permalink to &quot;法执&quot;">​</a></h1><h2 id="定义" tabindex="-1">定义 <a class="header-anchor" href="#定义" aria-label="Permalink to &quot;定义&quot;">​</a></h2><p>法执是对方法、理论、教条的执着——认为某个特定的方法或理论是绝对正确的，放之四海而皆准。</p><h2 id="了空居士原话" tabindex="-1">了空居士原话 <a class="header-anchor" href="#了空居士原话" aria-label="Permalink to &quot;了空居士原话&quot;">​</a></h2><blockquote><p>&quot;法尚应舍，何况非法——连佛法都要放下，何况那些不是法的东西。法是指南针，不是终点。&quot;</p></blockquote><blockquote><p>&quot;所谓佛法者，即非佛法——佛祖说的种种方法是对症下药，药方不能通用。不要将佛祖对甲说的话拿去给乙用。&quot;</p></blockquote><blockquote><p>&quot;无有定法名阿耨多罗三藐三菩提，亦无有定法如来可说——没有一个固定的方法叫做开悟。&quot;</p></blockquote><blockquote><p>&quot;法无定法，各人因缘不同。千万不要拿自己的法门去评判别人的。&quot;</p></blockquote><h2 id="法执误区的表现" tabindex="-1">法执误区的表现 <a class="header-anchor" href="#法执误区的表现" aria-label="Permalink to &quot;法执误区的表现&quot;">​</a></h2><ul><li>以为&quot;我修的法门最高&quot;</li><li>照搬别人的修行经验</li><li>以为经典上的字句就是绝对真理</li><li>执着于某种修行形式或仪式</li></ul><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/50-概念资料/dict-我执">我执</a> — 法执的根源在于我执</li><li><a href="/50-概念资料/dict-顽空">顽空</a> — 另一种极端</li></ul><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/10-核心模型/model-对法不执">对法不执</a> — 放下对方法的执着</li></ul><h2 id="修行实践" tabindex="-1">修行实践 <a class="header-anchor" href="#修行实践" aria-label="Permalink to &quot;修行实践&quot;">​</a></h2><ul><li>方法好就拿来用，不好就放下</li><li>不拿自己的标准去评判别人</li><li>具体问题具体分析，照搬等于死路</li></ul>',16)])])}const _=e(i,[["render",r]]);export{s as __pageData,_ as default};
